/* MF35 Explorer UI (Phase 2: application foundation).
 * Plain browser JavaScript, no build step, so index.html works from file://.
 * Data comes from window.MF35_DATA (generated by scripts/build-data.mjs);
 * all logic that can be tested without a DOM lives in core.js. */
(function () {
  'use strict';

  var DATA = window.MF35_DATA;
  var core = window.MF35Core;
  if (!DATA || !core) {
    document.getElementById('workspace').innerHTML =
      '<div class="page"><h1>Data not loaded</h1><p class="lede">Run <code>npm run build</code> to generate <code>app/data/mf35-data.js</code>, then reload.</p></div>';
    return;
  }

  /* ---------- State ---------- */
  var STORAGE_KEY = 'mf35.owner.v1';
  var index = core.indexHierarchy(DATA.hierarchy);
  var sourcesById = {};
  DATA.sources.forEach(function (s) { sourcesById[s.id] = s; });
  var config = DATA.configurations;
  var technical = DATA.technical;
  var axesById = {};
  config.variantAxes.forEach(function (a) { axesById[a.id] = a; });

  var state = {
    view: 'anatomy',
    selectedId: null,
    expanded: {},
    overrides: loadOverrides(),
    resolved: null,
    catalogue: { q: '', system: '', status: '', kind: 'component', fittedOnly: false },
    lastDecode: null
  };
  state.resolved = core.resolveConfiguration(config, state.overrides);
  var searchDocs = core.buildSearchIndex(index, sourcesById, technical);

  // Expand systems by default
  index.byId[index.rootId].childIds.forEach(function (id) { state.expanded[id] = false; });

  var $ = function (id) { return document.getElementById(id); };
  var el = {
    layout: $('main'), tree: $('tree'), workspace: $('workspace'), info: $('info'),
    breadcrumb: $('breadcrumb'), selectedId: $('selected-id'), banner: $('config-banner'),
    search: $('global-search'), results: $('search-results'), treeFilter: $('tree-filter'), scrim: $('scrim')
  };

  /* ---------- Helpers ---------- */
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  function nodeOf(id) { return index.byId[id] && index.byId[id].node; }
  function nameOf(id) { var n = nodeOf(id); return n ? n.name : id; }
  function statusBadge(status) {
    return '<span class="badge ' + status + '"><span class="status-dot ' + status + '"></span>' + esc(core.STATUS_LABELS[status]) + '</span>';
  }
  function missing(text) { return '<span class="missing">' + esc(text || 'Not yet documented') + '</span>'; }
  function optionLabel(axis, optId) {
    var a = axesById[axis];
    var o = a && a.options.filter(function (x) { return x.id === optId; })[0];
    return o ? o.label : optId;
  }
  function kindLabel(kind) {
    return { tractor: 'Tractor', system: 'System', assembly: 'Assembly', subassembly: 'Subassembly', component: 'Component' }[kind] || kind;
  }
  function loadOverrides() {
    try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}') || {}; } catch (e) { return {}; }
  }
  function saveOverrides() {
    try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state.overrides)); } catch (e) { /* storage unavailable: keep in memory */ }
    state.resolved = core.resolveConfiguration(config, state.overrides);
  }
  function sourceLinks(ids) {
    if (!ids || !ids.length) return missing('No source yet');
    return ids.map(function (id) {
      return '<a class="mono" href="#/research/' + esc(id) + '" title="' + esc(sourcesById[id] ? sourcesById[id].name : id) + '">' + esc(id) + '</a>';
    }).join(', ');
  }
  function go(hash) { if (location.hash === hash) route(); else location.hash = hash; }

  /* ---------- Routing ---------- */
  var VIEWS = ['anatomy', 'catalogue', 'exploded', 'technical', 'identification', 'tractor', 'research'];
  function route() {
    var parts = location.hash.replace(/^#\/?/, '').split('/');
    var view = VIEWS.indexOf(parts[0]) !== -1 ? parts[0] : 'anatomy';
    var arg = parts[1] ? decodeURIComponent(parts[1]) : null;
    state.view = view;
    if ((view === 'anatomy' || view === 'catalogue') && arg && index.byId[arg]) select(arg, { silentRoute: true });
    state.routeArg = arg;
    closeDrawers();
    render();
  }

  function select(id, opts) {
    if (!index.byId[id]) return;
    state.selectedId = id;
    // reveal in tree
    index.byId[id].path.forEach(function (pid) { if (pid !== index.rootId) state.expanded[pid] = true; });
    if (!(opts && opts.silentRoute)) {
      var target = (state.view === 'catalogue' ? '#/catalogue/' : '#/anatomy/') + encodeURIComponent(id);
      if (location.hash !== target) { history.replaceState(null, '', target); }
      render();
      if (window.matchMedia('(max-width: 980px)').matches && opts && opts.openInfo) { closeDrawers(); openDrawer('info'); }
    }
  }

  /* ---------- Render ---------- */
  function render() {
    el.layout.setAttribute('data-view', state.view);
    document.querySelectorAll('.main-nav a').forEach(function (a) {
      if (a.getAttribute('data-view') === state.view) a.setAttribute('aria-current', 'page'); else a.removeAttribute('aria-current');
    });
    renderBanner();
    if (state.view === 'anatomy') renderTree();
    renderWorkspace();
    renderInfo();
    renderBreadcrumb();
  }

  function renderBanner() {
    var r = state.resolved;
    var chips = [
      ['engine', 'Engine'], ['clutch', 'Clutch'], ['pto', 'PTO']
    ].map(function (pair) {
      var axis = pair[0];
      var cls = r.confirmed[axis] ? 'confirmed' : 'assumed';
      var val = optionLabel(axis, r.values[axis]);
      var suffix = r.confirmed[axis] ? '' : (r.owner[axis] ? ' (provisional)' : ' (unknown: showing default)');
      if (axis === 'engine' && r.owner.engineStatus === 'provisional' && !state.overrides.engine) suffix = ' (provisional)';
      return '<span class="config-chip ' + cls + '"><span class="dot"></span><strong>' + pair[1] + ':</strong> ' + esc(val) + esc(suffix) + '</span>';
    }).join('');
    var serial = r.owner.serialNumber ? esc((r.owner.serialPrefix ? r.owner.serialPrefix + ' ' : '') + r.owner.serialNumber) : 'not entered';
    el.banner.innerHTML = '<span class="config-chip"><strong>Your tractor:</strong> MF35, believed 1958 · serial ' + serial + '</span>' + chips +
      '<a href="#/tractor">Update my tractor →</a>';
  }

  /* ----- Tree ----- */
  function renderTree() {
    var filter = core.normalise(el.treeFilter.value);
    var matchIds = null;
    if (filter) {
      matchIds = {};
      index.order.forEach(function (id) {
        var n = index.byId[id].node;
        if (core.normalise(n.name).indexOf(filter) !== -1 || id.indexOf(filter.replace(/ /g, '-')) !== -1) {
          index.byId[id].path.forEach(function (p) { matchIds[p] = true; });
        }
      });
    }
    var html = [];
    index.byId[index.rootId].childIds.forEach(function (id) { treeNode(id, html, matchIds); });
    el.tree.innerHTML = html.join('') || '<p class="muted" style="padding:8px">No matches.</p>';
    var sel = el.tree.querySelector('[aria-selected="true"]');
    if (sel && sel.scrollIntoView) sel.scrollIntoView({ block: 'nearest' });
  }
  function treeNode(id, html, matchIds) {
    if (matchIds && !matchIds[id]) return;
    var e = index.byId[id];
    var n = e.node;
    var hasKids = e.childIds.length > 0;
    var open = matchIds ? true : !!state.expanded[id];
    var status = core.displayStatus(index, id, state.resolved);
    var app = core.applicability(index, id, state.resolved);
    var cls = 'tree-row kind-' + n.kind + (app.applies ? '' : ' not-fitted');
    html.push('<div class="' + cls + '" role="treeitem" tabindex="-1" data-id="' + esc(id) + '"' +
      (hasKids ? ' aria-expanded="' + open + '"' : '') +
      ' aria-selected="' + (state.selectedId === id) + '" aria-level="' + e.depth + '"' +
      (app.applies ? '' : ' title="Not fitted to the configuration being shown"') + '>' +
      (hasKids ? '<button class="twisty" data-toggle="' + esc(id) + '" tabindex="-1" aria-label="Toggle"><svg viewBox="0 0 24 24"><path d="M9 6l6 6-6 6"/></svg></button>' : '<span class="twisty"></span>') +
      '<span class="status-dot ' + status + '" title="' + esc(core.STATUS_LABELS[status]) + '"></span>' +
      '<span class="label">' + esc(n.name) + '</span>' +
      (n.quantity ? '<span class="qty">×' + n.quantity + '</span>' : '') +
      '</div>');
    if (hasKids && open) {
      html.push('<div class="tree-group" role="group">');
      e.childIds.forEach(function (c) { treeNode(c, html, matchIds); });
      html.push('</div>');
    }
  }

  /* ----- Workspace ----- */
  function renderWorkspace() {
    var fn = { anatomy: viewAnatomy, catalogue: viewCatalogue, exploded: viewExploded, technical: viewTechnical,
      identification: viewIdentification, tractor: viewTractor, research: viewResearch }[state.view];
    el.workspace.innerHTML = fn();
    if (state.view === 'catalogue') bindCatalogue();
    if (state.view === 'tractor') bindTractor();
    if (state.view === 'technical' || state.view === 'research') {
      if (state.routeArg) {
        var t = document.getElementById('anchor-' + state.routeArg);
        if (t) setTimeout(function () { t.scrollIntoView({ block: 'start' }); t.classList.add('selected'); }, 0);
      }
    }
  }

  // Schematic side elevation used until the Phase 3 model exists. Not to scale.
  var SCHEMATIC = [
    { id: 'bodywork', shape: '<rect class="shape" x="86" y="92" width="392" height="30" rx="8"/>', label: [282, 112, 'Bodywork & bonnet'] },
    { id: 'fuel', shape: '<rect class="shape" x="196" y="128" width="168" height="48" rx="6"/>', label: [280, 157, 'Fuel system'] },
    { id: 'electrical', shape: '<rect class="shape" x="372" y="128" width="106" height="48" rx="6"/>', label: [425, 157, 'Electrical'] },
    { id: 'cooling', shape: '<rect class="shape" x="88" y="128" width="100" height="160" rx="6"/>', label: [138, 212, 'Cooling'] },
    { id: 'engine', shape: '<rect class="shape" x="196" y="184" width="176" height="122" rx="6"/>', label: [284, 240, 'Engine (23C)'] },
    { id: 'clutch', shape: '<rect class="shape" x="380" y="196" width="62" height="104" rx="6"/>', label: [411, 252, 'Clutch'] },
    { id: 'transmission', shape: '<rect class="shape" x="450" y="204" width="122" height="92" rx="6"/>', label: [511, 254, 'Gearbox'] },
    { id: 'hydraulics', shape: '<rect class="shape" x="580" y="186" width="132" height="58" rx="6"/>', label: [646, 220, 'Hydraulic lift'] },
    { id: 'rear-axle', shape: '<rect class="shape" x="580" y="252" width="132" height="76" rx="6"/>', label: [646, 294, 'Rear axle & brakes'] },
    { id: 'pto', shape: '<rect class="shape" x="736" y="292" width="72" height="30" rx="6"/>', label: [772, 312, 'PTO'] },
    { id: 'linkage', shape: '<path class="shape" d="M736 214 h96 v58 h-96 z"/>', label: [784, 247, '3-point linkage'] },
    { id: 'front-axle', shape: '<rect class="shape" x="96" y="330" width="130" height="26" rx="6"/>', label: [161, 348, 'Front axle & steering'] }
  ];
  function viewAnatomy() {
    var activeSys = state.selectedId ? (index.byId[state.selectedId].depth === 0 ? null : index.byId[state.selectedId].path[1]) : null;
    var shapes = SCHEMATIC.map(function (s) {
      return '<g class="sys' + (activeSys === s.id ? ' active' : '') + '" data-sys="' + s.id + '" tabindex="0" role="button" aria-label="' + esc(nameOf(s.id)) + '">' +
        s.shape + '<text x="' + s.label[0] + '" y="' + s.label[1] + '" text-anchor="middle">' + esc(s.label[2]) + '</text></g>';
    }).join('');
    var wheelsActive = activeSys === 'wheels' ? ' active' : '';
    var svg =
      '<svg class="schematic" viewBox="60 72 830 396" preserveAspectRatio="xMidYMid meet" role="group" aria-label="Schematic map of tractor systems">' +
      '<line class="ground" x1="40" y1="430" x2="870" y2="430"/>' +
      '<g class="sys' + wheelsActive + '" data-sys="wheels" tabindex="0" role="button" aria-label="Wheels and tyres">' +
      '<circle class="shape wheel" cx="160" cy="370" r="58" style="fill:none;stroke-width:14;pointer-events:stroke"/>' +
      '<circle class="shape wheel" cx="646" cy="318" r="104" style="fill:none;stroke-width:20;pointer-events:stroke"/>' +
      '<text x="646" y="452" text-anchor="middle">Wheels & tyres</text></g>' +
      shapes +
      '<path class="flow" d="M372 268 H380 M442 268 H450 M572 268 H580 M712 306 H736"/>' +
      '</svg>';
    var sel = state.selectedId ? nodeOf(state.selectedId) : null;
    return '<div class="ws-anatomy">' +
      '<div class="viewport">' +
      '<div class="viewport-label"><strong>Schematic systems map</strong>: not to scale. The interactive 3D model replaces this in Phase 3.</div>' +
      svg + '</div>' +
      '<div class="toolbar" role="toolbar" aria-label="View controls">' +
      '<div class="group"><button class="tool" data-act="reset">Reset view</button><button class="tool" data-act="up"' + (sel && index.byId[state.selectedId].parentId ? '' : ' disabled') + '>Up one level</button></div>' +
      '<div class="group"><button class="tool" disabled title="Phase 3">Isolate</button><button class="tool" disabled title="Phase 3">Hide</button><button class="tool" disabled title="Phase 3">Show all</button></div>' +
      '<div class="group"><label class="note" for="explode">Explode</label><input id="explode" type="range" min="0" max="100" value="0" disabled title="Phase 4"></div>' +
      '<div class="group"><button class="tool" disabled title="Phase 3">Front</button><button class="tool" disabled title="Phase 3">Side</button><button class="tool" disabled title="Phase 3">Rear</button><button class="tool" disabled title="Phase 3">Top</button></div>' +
      '<span class="note">Greyed controls arrive with the 3D model (Phases 3–4).</span>' +
      '</div></div>';
  }

  function catalogueRows() {
    var c = state.catalogue;
    var rows;
    if (c.q) {
      rows = core.search(searchDocs, c.q, 400).filter(function (r) { return r.doc.kind === 'component'; }).map(function (r) { return r.doc.id; });
    } else {
      rows = index.order.filter(function (id) { return id !== index.rootId; });
    }
    return rows.filter(function (id) {
      var e = index.byId[id];
      if (c.kind === 'component' && e.node.kind !== 'component') return false;
      if (c.system && e.path[1] !== c.system) return false;
      if (c.status && core.displayStatus(index, id, state.resolved) !== c.status) return false;
      if (c.fittedOnly && !core.applicability(index, id, state.resolved).applies) return false;
      return true;
    });
  }
  function viewCatalogue() {
    var c = state.catalogue;
    var systems = index.byId[index.rootId].childIds;
    var rows = catalogueRows();
    var body = rows.map(function (id) {
      var e = index.byId[id], n = e.node;
      var st = core.displayStatus(index, id, state.resolved);
      var app = core.applicability(index, id, state.resolved);
      var assembly = e.path.slice(1, -1).map(nameOf).join(' › ');
      var pn = n.oemPartNumber ? '<span class="mono">' + esc(n.oemPartNumber) + '</span>' :
        (n.supplierClaimedOem && n.supplierClaimedOem.length ? '<span class="badge claim" title="Supplier-claimed, not verified">' + n.supplierClaimedOem.length + ' unverified ref' + (n.supplierClaimedOem.length > 1 ? 's' : '') + '</span>' : '<span class="muted">Not yet documented</span>');
      return '<tr class="clickable' + (state.selectedId === id ? ' selected' : '') + '" data-id="' + esc(id) + '">' +
        '<td><strong>' + esc(n.name) + '</strong>' + (app.applies ? '' : ' <span class="badge neutral">not fitted to shown config</span>') + '<div class="muted mono">' + esc(id) + '</div></td>' +
        '<td>' + pn + '</td>' +
        '<td class="muted">' + esc(assembly) + '</td>' +
        '<td class="mono">' + (n.quantity ? n.quantity : '<span class="muted">–</span>') + '</td>' +
        '<td>' + statusBadge(st) + '</td>' +
        '<td><a href="#/anatomy/' + encodeURIComponent(id) + '">View</a></td></tr>';
    }).join('');
    return '<div class="page">' +
      '<div class="page-head"><div><h1>Parts catalogue</h1><p class="lede">Every component identified so far. Original part numbers appear only once checked against the AGCO parts book (819045M4); supplier numbers are shown as unverified references.</p></div></div>' +
      '<div class="filters">' +
      '<input id="cat-q" type="search" placeholder="Search name, part number, assembly…" value="' + esc(c.q) + '" aria-label="Search catalogue">' +
      '<select id="cat-system" aria-label="System"><option value="">All systems</option>' + systems.map(function (s) { return '<option value="' + s + '"' + (c.system === s ? ' selected' : '') + '>' + esc(nameOf(s)) + '</option>'; }).join('') + '</select>' +
      '<select id="cat-status" aria-label="Verification status"><option value="">Any status</option>' + Object.keys(core.STATUS_LABELS).map(function (s) { return '<option value="' + s + '"' + (c.status === s ? ' selected' : '') + '>' + core.STATUS_LABELS[s] + '</option>'; }).join('') + '</select>' +
      '<select id="cat-kind" aria-label="Level"><option value="component"' + (c.kind === 'component' ? ' selected' : '') + '>Components only</option><option value=""' + (c.kind === '' ? ' selected' : '') + '>All levels</option></select>' +
      '<label class="note" style="display:flex;align-items:center;gap:6px"><input id="cat-fitted" type="checkbox"' + (c.fittedOnly ? ' checked' : '') + '> Fitted to shown configuration</label>' +
      '</div>' +
      '<div class="result-count">' + rows.length + ' item' + (rows.length === 1 ? '' : 's') + '</div>' +
      '<div class="table-wrap"><table><thead><tr><th>Component</th><th>Original part no.</th><th>Assembly</th><th>Qty</th><th>Status</th><th>3D</th></tr></thead><tbody>' +
      (body || '<tr><td colspan="6" class="muted">No components match. Try fewer words or another spelling.</td></tr>') +
      '</tbody></table></div></div>';
  }
  function bindCatalogue() {
    var c = state.catalogue;
    var q = $('cat-q');
    var rerender = function () {
      var pos = q.selectionStart;
      renderWorkspace();
      var nq = $('cat-q'); nq.focus(); try { nq.setSelectionRange(pos, pos); } catch (e) { /* ignore */ }
    };
    q.addEventListener('input', function () { c.q = q.value; rerender(); });
    $('cat-system').addEventListener('change', function (e) { c.system = e.target.value; renderWorkspace(); });
    $('cat-status').addEventListener('change', function (e) { c.status = e.target.value; renderWorkspace(); });
    $('cat-kind').addEventListener('change', function (e) { c.kind = e.target.value; renderWorkspace(); });
    $('cat-fitted').addEventListener('change', function (e) { c.fittedOnly = e.target.checked; renderWorkspace(); });
  }

  var DIAGRAMS = [
    ['engine', 'Complete engine'], ['cylinder-head-assy', 'Cylinder head'], ['engine-block-assy', 'Cylinder block'],
    ['crank-assy', 'Crankshaft, pistons & rods'], ['timing-assy', 'Camshaft & timing chain'], ['fuel-injection', 'Fuel injection'],
    ['cooling', 'Cooling system'], ['clutch', 'Clutch'], ['transmission', 'Gearbox'], ['differential', 'Differential'],
    ['rear-axle', 'Rear axle'], ['lift-cover', 'Hydraulic lift'], ['hyd-pump', 'Hydraulic pump'], ['pto', 'PTO'],
    ['front-axle', 'Front axle & steering'], ['brakes', 'Braking system'], ['linkage', 'Three-point linkage']
  ];
  function viewExploded() {
    return '<div class="page"><div class="page-head"><div><h1>Exploded views</h1><p class="lede">Numbered, original exploded diagrams for each major assembly.</p></div></div>' +
      '<div class="placeholder-note"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7.5v.5"/></svg><div><strong>Placeholder.</strong> Diagrams are drawn in Phase 6 and linked to the 3D explode in Phase 4. Each card already opens its assembly and parts list.</div></div>' +
      '<div class="diagram-list">' + DIAGRAMS.map(function (d) {
        var e = index.byId[d[0]];
        var count = 0;
        (function walk(id) { index.byId[id].childIds.forEach(function (c) { count++; walk(c); }); })(d[0]);
        return '<a class="card diagram-card" href="#/anatomy/' + d[0] + '" style="text-decoration:none;color:inherit"><h3>' + esc(d[1]) + '</h3><p>' + count + ' parts listed · diagram not yet drawn</p>' +
          '<p style="margin-top:6px">' + statusBadge(core.displayStatus(index, d[0], state.resolved)) + '</p></a>';
      }).join('') + '</div></div>';
  }

  function viewTechnical() {
    return '<div class="page"><div class="page-head"><div><h1>Technical information</h1><p class="lede">Only figures with a cited source are shown, each with its verification status. Where sources disagree or a figure looks wrong, it is held back.</p></div></div>' +
      '<div class="tech-grid">' + technical.sections.map(function (sec) {
        return '<section class="card" id="anchor-' + sec.id + '"><div class="card-pad" style="padding-bottom:6px"><h2 style="margin:0 0 8px">' + esc(sec.title) + '</h2></div>' +
          '<div class="table-wrap" style="border:0;border-radius:0;box-shadow:none"><table><thead><tr><th style="width:26%">Item</th><th>Value</th><th style="width:150px">Status</th><th style="width:150px">Sources</th></tr></thead><tbody>' +
          sec.rows.map(function (row) {
            if (row.display === false) {
              return '<tr class="tech-row-withheld"><td>' + esc(row.label) + '</td><td colspan="2">Withheld until checked against the service manual</td><td>' + sourceLinks(row.sources) + '</td></tr>';
            }
            return '<tr><td>' + esc(row.label) + '</td><td>' + (row.value ? esc(row.value) : missing()) + '</td><td>' + statusBadge(row.status) + '</td><td>' + sourceLinks(row.sources) + '</td></tr>';
          }).join('') + '</tbody></table></div>' +
          (sec.explainer ? '<p class="explainer"><strong>How it works.</strong> ' + esc(sec.explainer) + '</p>' : '') +
          '</section>';
      }).join('') + '</div></div>';
  }

  function viewIdentification() {
    var idn = technical.identification;
    var byPos = [1, 2, 3].map(function (p) { return idn.prefixLetters.filter(function (l) { return l.position === p; }); });
    var years = config.productionYears.map(function (y, i, arr) {
      var next = arr[i + 1];
      return '<tr' + (y.year === 1958 ? ' class="selected"' : '') + '><td><strong>' + y.year + '</strong></td><td class="mono">' + y.firstSerial + (next ? '–' + (next.firstSerial - 1) : ' onward') + '</td></tr>';
    }).join('');
    return '<div class="page"><div class="page-head"><div><h1>Identify your tractor</h1><p class="lede">How to pin down exactly which parts fit. Until the serial plate and clutch are checked, parts that differ between versions are marked <em>variant dependent</em>.</p></div><a class="btn" href="#/tractor" style="display:inline-grid;place-items:center;text-decoration:none">Enter my serial number</a></div>' +
      '<ol class="steps">' + idn.steps.map(function (s) {
        return '<li class="card"><div><h3>' + esc(s.title) + '</h3><p>' + esc(s.text) + '</p><p class="muted" style="font-size:12px;margin-top:4px">Sources: ' + sourceLinks(s.sources) + '</p></div></li>';
      }).join('') + '</ol>' +
      '<h2>Serial prefix letters</h2><div class="note-box" style="margin-bottom:12px">' + statusBadge(idn.prefixStatus) + ' ' + esc(idn.prefixNote) + ' Source: ' + sourceLinks(idn.prefixSources) + '</div>' +
      '<div class="letters">' + ['1st letter: chassis', '2nd letter: fuel', '3rd letter: clutch'].map(function (t, i) {
        return '<div class="card card-pad"><h3>' + t + '</h3>' + byPos[i].map(function (l) { return '<div class="letter-row"><b>' + l.letter + '</b><span>' + esc(l.meaning) + '</span></div>'; }).join('') + '</div>';
      }).join('') + '</div>' +
      '<h2>Coventry serial numbers by year</h2><p class="lede" style="margin-bottom:10px">First serial of each year. Sources: ' + sourceLinks(config.productionYearsSources) + '</p>' +
      '<div class="table-wrap" style="max-width:420px"><table><thead><tr><th>Year</th><th>Serial range</th></tr></thead><tbody>' + years + '</tbody></table></div>' +
      '</div>';
  }

  function viewTractor() {
    var r = state.resolved;
    var o = state.overrides;
    var axisSelect = function (axis, label, hint) {
      var a = axesById[axis];
      var opts = a.options.filter(function (x) { return !x.outOfScope || axis === 'engine'; });
      var current = o[axis] || '';
      var fileVal = config.ownerTractor[axis];
      return '<div class="field"><label for="ax-' + axis + '">' + esc(label) + '</label><select id="ax-' + axis + '" data-axis="' + axis + '"' + (axis === 'pto' ? ' disabled' : '') + '>' +
        '<option value="">' + (axis === 'pto' && r.confirmed.clutch ? 'From clutch: ' + esc(optionLabel('pto', r.values.pto)) : fileVal ? 'As recorded: ' + esc(optionLabel(axis, fileVal)) : 'Unknown') + '</option>' +
        opts.map(function (x) { return '<option value="' + x.id + '"' + (current === x.id ? ' selected' : '') + '>' + esc(x.label) + '</option>'; }).join('') +
        '</select><div class="hint">' + esc(hint) + '</div></div>';
    };
    var d = state.lastDecode;
    var decodeHtml = '';
    if (d) {
      decodeHtml = '<div class="decode card card-pad"><h3 style="font-size:14px;margin-bottom:8px">Reading of ' + esc(d.input) + '</h3><dl class="fields">' +
        '<dt>Prefix</dt><dd>' + (d.prefix ? d.letters.map(function (l) { return '<b class="mono">' + l.letter + '</b> ' + (l.meaning ? esc(l.meaning) : missing('unknown letter')); }).join('<br>') : missing('none entered')) + '</dd>' +
        '<dt>Number</dt><dd class="mono">' + (d.number != null ? d.number : '–') + '</dd>' +
        '<dt>Year</dt><dd>' + (d.year ? d.year + (d.inTargetYear ? ' ✓' : '') : missing('outside documented range')) + '</dd></dl>' +
        d.warnings.map(function (w) { return '<div class="warn">' + esc(w) + '</div>'; }).join('') +
        (d.number != null ? '<div class="actions"><button class="btn" id="apply-serial">Use this for my tractor</button></div>' : '') +
        '<p class="muted" style="font-size:12px;margin:10px 0 0">The prefix letter meanings come from one supplier source and are not yet confirmed against a UK 1958 plate.</p></div>';
    }
    return '<div class="page"><div class="page-head"><div><h1>My tractor</h1><p class="lede">Record what you find on the tractor. The catalogue and banner update straight away. These choices are saved only in this browser. To make them permanent for everyone, they also need adding to <code>data/configurations.json</code>.</p></div></div>' +
      '<section class="card card-pad"><h2 style="margin:0 0 10px">Serial number</h2>' +
      '<div class="form-grid"><div class="field"><label for="serial">Serial plate (prefix and number)</label><input id="serial" placeholder="e.g. SDM 105432" value="' + esc(o.serialPrefix || o.serialNumber ? ((o.serialPrefix || '') + ' ' + (o.serialNumber || '')).trim() : '') + '"><div class="hint">Found on the dash / instrument console.</div></div>' +
      '<div class="field"><label for="engine-no">Engine number</label><input id="engine-no" placeholder="Stamped above the dynamo, RH side" value="' + esc(o.engineNumber || '') + '"><div class="hint">Recorded for reference only.</div></div></div>' +
      '<div class="actions"><button class="btn" id="decode-serial">Read serial</button></div>' + decodeHtml + '</section>' +
      '<section class="card card-pad" style="margin-top:16px"><h2 style="margin:0 0 10px">Equipment</h2><div class="form-grid">' +
      axisSelect('clutch', 'Clutch', 'Half-pedal test: if the PTO keeps turning, it is dual-stage.') +
      axisSelect('pto', 'PTO drive', 'Set automatically from the clutch.') +
      axisSelect('engine', 'Engine', 'A 3-cylinder engine means a later Perkins replacement.') +
      axisSelect('electrics', 'Electrical system', 'Check the dynamo label and battery arrangement.') +
      axisSelect('coldStart', 'Cold-start equipment', 'Heater plugs in each cylinder = cold-climate.') +
      axisSelect('diffLock', 'Differential lock', 'Look for a diff-lock pedal.') +
      '</div><div class="actions"><button class="btn secondary" id="reset-owner">Clear my entries</button></div>' +
      '<p class="muted" style="font-size:12.5px;margin:12px 0 0">Currently showing: ' + core.AXIS_KEYS.map(function (a) { return esc(axesById[a].label) + ' = ' + esc(optionLabel(a, r.values[a])) + (r.confirmed[a] ? '' : ' (assumed)'); }).join(' · ') + '</p></section>' +
      '<section class="card card-pad" style="margin-top:16px"><h2 style="margin:0 0 6px">Recorded observations</h2>' +
      ((config.ownerTractor.observations || []).map(function (ob) { return '<p style="margin:6px 0"><strong>' + esc(ob.date) + ':</strong> ' + esc(ob.observation) + '<br><span class="muted">' + esc(ob.inference) + '</span></p>'; }).join('') || missing('None yet')) +
      '</section></div>';
  }
  function bindTractor() {
    $('decode-serial').addEventListener('click', function () {
      state.lastDecode = core.decodeSerial($('serial').value, config, technical);
      renderWorkspace();
    });
    $('serial').addEventListener('keydown', function (e) { if (e.key === 'Enter') $('decode-serial').click(); });
    $('engine-no').addEventListener('change', function (e) { state.overrides.engineNumber = e.target.value.trim() || undefined; saveOverrides(); });
    var apply = $('apply-serial');
    if (apply) apply.addEventListener('click', function () {
      var d = state.lastDecode;
      state.overrides.serialPrefix = d.prefix || undefined;
      state.overrides.serialNumber = d.number;
      Object.keys(d.axisValues).forEach(function (axis) { state.overrides[axis] = d.axisValues[axis]; });
      saveOverrides(); render();
    });
    document.querySelectorAll('[data-axis]').forEach(function (s) {
      s.addEventListener('change', function () {
        var axis = s.getAttribute('data-axis');
        if (s.value) state.overrides[axis] = s.value; else delete state.overrides[axis];
        saveOverrides(); render();
      });
    });
    $('reset-owner').addEventListener('click', function () {
      state.overrides = {}; state.lastDecode = null; saveOverrides(); render();
    });
  }

  function viewResearch() {
    var cov = core.coverage(index);
    var sys = index.byId[index.rootId].childIds;
    var tot = { total: 0, verified: 0, 'partially-verified': 0, unverified: 0, 'variant-dependent': 0, oem: 0 };
    sys.forEach(function (s) { Object.keys(tot).forEach(function (k) { tot[k] += cov[s][k]; }); });
    var claims = 0;
    index.order.forEach(function (id) { if ((nodeOf(id).supplierClaimedOem || []).length) claims++; });
    var stat = function (n, l) { return '<div class="card stat"><div class="num">' + n + '</div><div class="lbl">' + l + '</div></div>'; };
    var bar = function (c) {
      var pct = function (k) { return c.total ? (100 * c[k] / c.total) : 0; };
      return '<div class="bar" title="verified / partially verified / variant dependent"><span class="b-verified" style="width:' + pct('verified') + '%"></span><span class="b-partial" style="width:' + pct('partially-verified') + '%"></span><span class="b-variant" style="width:' + pct('variant-dependent') + '%"></span></div>';
    };
    return '<div class="page"><div class="page-head"><div><h1>Research status</h1><p class="lede">How much of the tractor is documented, and from what. Nothing is marked verified until it has been checked against an original Massey Ferguson publication.</p></div></div>' +
      '<div class="stats">' + stat(tot.total, 'Items identified') + stat(tot.verified, 'Verified') + stat(tot['partially-verified'], 'Partially verified') +
      stat(tot['variant-dependent'], 'Variant dependent') + stat(tot.unverified, 'Unverified') + stat(tot.oem, 'Confirmed OEM numbers') + stat(claims, 'With unverified supplier refs') + stat(0, 'In 3D (Phase 3)') + '</div>' +
      '<h2>By system</h2><div class="table-wrap"><table><thead><tr><th>System</th><th>Items</th><th>Verified</th><th>Partial</th><th>Variant</th><th>Unverified</th><th>Progress</th></tr></thead><tbody>' +
      sys.map(function (s) { var c = cov[s]; return '<tr class="clickable" data-goto="' + s + '"><td><strong>' + esc(nameOf(s)) + '</strong></td><td class="mono">' + c.total + '</td><td class="mono">' + c.verified + '</td><td class="mono">' + c['partially-verified'] + '</td><td class="mono">' + c['variant-dependent'] + '</td><td class="mono">' + c.unverified + '</td><td>' + bar(c) + '</td></tr>'; }).join('') +
      '</tbody></table></div>' +
      '<h2>Source register</h2><div class="table-wrap"><table><thead><tr><th>Id</th><th>Source</th><th>Grade</th><th>Read</th></tr></thead><tbody>' +
      DATA.sources.map(function (s) {
        return '<tr id="anchor-' + s.id + '"><td class="mono">' + s.id + '</td><td>' + (s.url ? '<a href="' + esc(s.url) + '" target="_blank" rel="noopener">' + esc(s.name) + '</a>' : esc(s.name)) +
          (s.extracted && s.extracted.length ? '<div class="muted" style="font-size:12px;margin-top:2px">' + esc(s.extracted[0]) + (s.extracted.length > 1 ? ' (+' + (s.extracted.length - 1) + ' more)' : '') + '</div>' : '') +
          (s.conflicts && s.conflicts.length ? '<div style="font-size:12px;color:#8a5a10;margin-top:2px">Conflict: ' + esc(s.conflicts[0]) + '</div>' : '') + '</td>' +
          '<td>' + esc(s.reliability) + '</td><td>' + (s.accessed ? esc(s.dateResearched) : '<span class="badge partially-verified">not yet obtained</span>') + '</td></tr>';
      }).join('') + '</tbody></table></div></div>';
  }

  /* ----- Info panel ----- */
  function renderInfo() {
    var id = state.selectedId;
    if (!id) {
      el.info.innerHTML = '<div class="info-empty"><h2>Select a component</h2><p>Choose an assembly from the list, click a system on the map, or search for a part. Its record appears here: part number, function, compatibility, sources and suppliers.</p>' +
        '<p style="margin-top:14px"><strong>Status key</strong></p><div class="chips" style="flex-direction:column;align-items:flex-start;gap:8px">' +
        Object.keys(core.STATUS_LABELS).map(statusBadge).join('') + '</div></div>';
      return;
    }
    var e = index.byId[id], n = e.node;
    var st = core.displayStatus(index, id, state.resolved);
    var app = core.applicability(index, id, state.resolved);
    var constraints = core.inheritedAppliesTo(index, id);
    var compat = Object.keys(constraints).map(function (axis) {
      return esc(axesById[axis].label) + ': ' + constraints[axis].map(function (o) { return esc(optionLabel(axis, o)); }).join(' or ');
    });
    var fitted = app.applies
      ? (app.variant ? '<span class="badge variant-dependent">Depends on unconfirmed equipment</span>' : '<span class="badge neutral">Fits the configuration shown</span>')
      : '<span class="badge neutral">Not fitted to the configuration shown</span>';
    var siblings = e.parentId ? index.byId[e.parentId].childIds.filter(function (c) { return c !== id; }) : [];
    var chip = function (cid) { return '<a class="chip" href="#/anatomy/' + encodeURIComponent(cid) + '"><span class="status-dot ' + core.displayStatus(index, cid, state.resolved) + '"></span>' + esc(nameOf(cid)) + '</a>'; };
    var srcs = (n.sources || []).map(function (sid) {
      var s = sourcesById[sid];
      if (!s) return '';
      return '<li><span class="src-id">' + sid + '</span>' + (s.url ? '<a href="' + esc(s.url) + '" target="_blank" rel="noopener">' + esc(s.name) + '</a>' : esc(s.name)) + '<div class="source-grade">' + esc(s.reliability) + (s.accessed ? ' · read ' + esc(s.dateResearched) : ' · not yet obtained') + '</div></li>';
    }).join('');
    var claims = (n.supplierClaimedOem || []);

    el.info.innerHTML =
      '<div class="info-head"><button class="text-btn only-mobile" data-close-info style="float:right">Close</button><div class="info-kind">' + kindLabel(n.kind) + (e.depth > 1 ? ' · ' + esc(nameOf(e.path[1])) : '') + '</div>' +
      '<h2>' + esc(n.name) + '</h2>' + statusBadge(st) + ' <span class="info-id">' + esc(id) + '</span></div>' +

      '<div class="info-section"><h3>Identification</h3><dl class="fields">' +
      '<dt>Original part no.</dt><dd>' + (n.oemPartNumber ? '<span class="mono">' + esc(n.oemPartNumber) + '</span>' : missing('Not yet documented (needs parts book 819045M4)')) + '</dd>' +
      '<dt>Other references</dt><dd>' + (claims.length ? '<div class="chips">' + claims.map(function (c) { return '<span class="chip mono" style="cursor:default">' + esc(c) + '</span>'; }).join('') + '</div><div style="margin-top:4px"><span class="badge claim">Supplier/forum claim, unverified</span></div>' : missing()) + '</dd>' +
      '<dt>Quantity</dt><dd>' + (n.quantity ? n.quantity + ' per tractor' : missing()) + '</dd>' +
      '<dt>Assembly</dt><dd>' + (e.parentId && e.parentId !== index.rootId ? esc(nameOf(e.parentId)) : esc(nameOf(index.rootId))) + '</dd></dl></div>' +

      '<div class="info-section"><h3>What it does</h3><dl class="fields">' +
      '<dt>Description</dt><dd>' + (n.description ? esc(n.description) : missing()) + '</dd>' +
      '<dt>Function</dt><dd>' + (n.function ? esc(n.function) : missing()) + '</dd>' +
      '<dt>Location</dt><dd>' + (n.location ? esc(n.location) : missing()) + '</dd>' +
      '<dt>Specifications</dt><dd>' + (n.specifications && Object.keys(n.specifications).length ? Object.keys(n.specifications).map(function (k) { return esc(k) + ': ' + esc(n.specifications[k]); }).join('<br>') : missing()) + '</dd></dl>' +
      (n.notes ? '<div class="note-box" style="margin-top:10px"><strong>Research note:</strong> ' + esc(n.notes) + '</div>' : '') + '</div>' +

      '<div class="info-section"><h3>Compatibility</h3><dl class="fields">' +
      '<dt>Tractor</dt><dd>MF35, Coventry, 1958 (serial 79553–125067)</dd>' +
      '<dt>Applies to</dt><dd>' + (compat.length ? compat.join('<br>') : 'All 1958 MF35 diesel configurations in scope') + '</dd>' +
      '<dt>Your tractor</dt><dd>' + fitted + '</dd></dl>' +
      (app.variant ? '<p class="muted" style="font-size:12.5px;margin:8px 0 0">Check this against your tractor before ordering. <a href="#/identification">How to identify it</a>.</p>' : '') + '</div>' +

      '<div class="info-section"><h3>Hierarchy</h3><div class="chips">' + e.path.slice(0, -1).map(chip).join('<span class="muted">›</span>') + '</div>' +
      (e.childIds.length ? '<h3 style="margin-top:12px">Contains (' + e.childIds.length + ')</h3><div class="chips">' + e.childIds.map(chip).join('') + '</div>' : '') +
      (siblings.length ? '<h3 style="margin-top:12px">Related</h3><div class="chips">' + siblings.slice(0, 10).map(chip).join('') + (siblings.length > 10 ? '<span class="muted">+' + (siblings.length - 10) + ' more</span>' : '') + '</div>' : '') + '</div>' +

      '<div class="info-section"><h3>Diagram and 3D</h3><dl class="fields">' +
      '<dt>Exploded diagram</dt><dd>' + missing('Not yet drawn (Phase 6)') + '</dd>' +
      '<dt>3D object</dt><dd><span class="mono">' + esc(id) + '</span> · ' + missing('not yet modelled (Phase 3)') + '</dd></dl></div>' +

      '<div class="info-section"><h3>Purchase options (UK)</h3>' + missing('No verified UK supplier reference yet. Suppliers are added in Phase 7, and only where the part number matches the parts book.') + '</div>' +

      '<div class="info-section"><h3>Sources</h3>' + (srcs ? '<ul class="source-list">' + srcs + '</ul>' : missing('No source cited yet: existence assumed from the product scope list')) + '</div>';
  }

  /* ----- Breadcrumb ----- */
  function renderBreadcrumb() {
    var viewNames = { anatomy: 'Tractor Anatomy', catalogue: 'Parts Catalogue', exploded: 'Exploded Views', technical: 'Technical Information', identification: 'Identification', tractor: 'My Tractor', research: 'Research Status' };
    var html = '<a href="#/' + state.view + '">' + viewNames[state.view] + '</a>';
    if (state.selectedId && (state.view === 'anatomy' || state.view === 'catalogue')) {
      index.byId[state.selectedId].path.forEach(function (pid, i, arr) {
        html += '<span class="sep">›</span><a href="#/' + state.view + '/' + encodeURIComponent(pid) + '"' + (i === arr.length - 1 ? ' aria-current="page"' : '') + '>' + esc(pid === index.rootId ? 'MF35' : nameOf(pid)) + '</a>';
      });
    }
    el.breadcrumb.innerHTML = html;
    el.selectedId.textContent = state.selectedId ? state.selectedId : '';
  }

  /* ---------- Global search ---------- */
  var activeResult = -1;
  function renderSearch() {
    var q = el.search.value;
    if (!q.trim()) { el.results.hidden = true; el.search.setAttribute('aria-expanded', 'false'); return; }
    var res = core.search(searchDocs, q, 12);
    activeResult = res.length ? 0 : -1;
    el.results.innerHTML = res.length ? res.map(function (r, i) {
      var d = r.doc;
      var path, badge;
      if (d.kind === 'component') {
        path = index.byId[d.id].path.slice(1, -1).map(nameOf).join(' › ') || 'System';
        badge = statusBadge(core.displayStatus(index, d.id, state.resolved));
      } else {
        path = 'Technical information';
        badge = '<span class="badge neutral">Spec</span>';
      }
      return '<div class="search-result" role="option" id="sr-' + i + '" data-kind="' + d.kind + '" data-id="' + esc(d.id) + '" aria-selected="' + (i === 0) + '">' +
        '<span class="sr-title">' + esc(d.title) + '</span>' + badge + '<span class="sr-path">' + esc(path) + '</span></div>';
    }).join('') : '<div class="search-empty">No matches for “' + esc(q) + '”. Try a shorter word or a part number.</div>';
    el.results.hidden = false;
    el.search.setAttribute('aria-expanded', 'true');
  }
  function openResult(node) {
    if (!node) return;
    var kind = node.getAttribute('data-kind'), id = node.getAttribute('data-id');
    el.results.hidden = true;
    el.search.blur();
    if (kind === 'component') {
      state.view = 'anatomy';
      go('#/anatomy/' + encodeURIComponent(id));
      select(id, { openInfo: true });
    } else {
      go('#/technical/' + id.split(':')[0]);
    }
  }

  /* ---------- Drawers (mobile) ---------- */
  function openDrawer(which) {
    document.body.classList.add(which + '-open');
    el.scrim.hidden = false;
    $('toggle-' + which).setAttribute('aria-expanded', 'true');
  }
  function closeDrawers() {
    document.body.classList.remove('tree-open', 'info-open');
    el.scrim.hidden = true;
    ['tree', 'info'].forEach(function (w) { $('toggle-' + w).setAttribute('aria-expanded', 'false'); });
  }

  /* ---------- Events ---------- */
  el.tree.addEventListener('click', function (e) {
    var tog = e.target.closest('[data-toggle]');
    if (tog) { var tid = tog.getAttribute('data-toggle'); state.expanded[tid] = !state.expanded[tid]; renderTree(); e.stopPropagation(); return; }
    var row = e.target.closest('.tree-row');
    if (row) {
      var id = row.getAttribute('data-id');
      if (index.byId[id].childIds.length && state.selectedId === id) state.expanded[id] = !state.expanded[id];
      select(id, { openInfo: true });
    }
  });
  el.tree.addEventListener('dblclick', function (e) {
    var row = e.target.closest('.tree-row');
    if (row) { var id = row.getAttribute('data-id'); state.expanded[id] = true; renderTree(); }
  });
  el.tree.addEventListener('keydown', function (e) {
    var rows = Array.prototype.slice.call(el.tree.querySelectorAll('.tree-row'));
    var cur = rows.findIndex(function (r) { return r.getAttribute('aria-selected') === 'true'; });
    var id = cur >= 0 ? rows[cur].getAttribute('data-id') : null;
    var next = null;
    if (e.key === 'ArrowDown') next = rows[Math.min(rows.length - 1, cur + 1)];
    else if (e.key === 'ArrowUp') next = rows[Math.max(0, cur - 1)];
    else if (e.key === 'ArrowRight' && id && index.byId[id].childIds.length) { state.expanded[id] = true; renderTree(); }
    else if (e.key === 'ArrowLeft' && id) {
      if (state.expanded[id]) { state.expanded[id] = false; renderTree(); }
      else if (index.byId[id].parentId && index.byId[id].parentId !== index.rootId) select(index.byId[id].parentId);
    } else return;
    e.preventDefault();
    if (next) { select(next.getAttribute('data-id')); var s = el.tree.querySelector('[aria-selected="true"]'); if (s) s.focus(); }
  });
  el.treeFilter.addEventListener('input', renderTree);
  $('tree-expand').addEventListener('click', function () { index.order.forEach(function (id) { if (index.byId[id].childIds.length) state.expanded[id] = true; }); renderTree(); });
  $('tree-collapse').addEventListener('click', function () { state.expanded = {}; renderTree(); });

  el.workspace.addEventListener('click', function (e) {
    var sys = e.target.closest('[data-sys]');
    if (sys) { select(sys.getAttribute('data-sys'), { openInfo: true }); return; }
    var act = e.target.closest('[data-act]');
    if (act) {
      var a = act.getAttribute('data-act');
      if (a === 'reset') { state.selectedId = null; history.replaceState(null, '', '#/anatomy'); render(); }
      if (a === 'up' && state.selectedId) { var p = index.byId[state.selectedId].parentId; if (p) select(p); }
      return;
    }
    var row = e.target.closest('tr[data-id]');
    if (row && !e.target.closest('a')) { select(row.getAttribute('data-id'), { openInfo: true }); return; }
    var g = e.target.closest('tr[data-goto]');
    if (g) { go('#/anatomy/' + g.getAttribute('data-goto')); }
  });
  el.workspace.addEventListener('keydown', function (e) {
    var sys = e.target.closest && e.target.closest('[data-sys]');
    if (sys && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); select(sys.getAttribute('data-sys'), { openInfo: true }); }
  });

  el.search.addEventListener('input', renderSearch);
  el.search.addEventListener('focus', renderSearch);
  el.search.addEventListener('keydown', function (e) {
    var items = el.results.querySelectorAll('.search-result');
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (!items.length) return;
      activeResult = (activeResult + (e.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length;
      items.forEach(function (it, i) { it.setAttribute('aria-selected', String(i === activeResult)); });
      items[activeResult].scrollIntoView({ block: 'nearest' });
    } else if (e.key === 'Enter') {
      openResult(items[activeResult]);
    } else if (e.key === 'Escape') {
      el.results.hidden = true; el.search.blur();
    }
  });
  el.results.addEventListener('mousedown', function (e) { var r = e.target.closest('.search-result'); if (r) { e.preventDefault(); openResult(r); } });
  document.addEventListener('click', function (e) { if (!e.target.closest('.search')) { el.results.hidden = true; el.search.setAttribute('aria-expanded', 'false'); } });
  document.addEventListener('keydown', function (e) {
    if (e.key === '/' && document.activeElement.tagName !== 'INPUT' && document.activeElement.tagName !== 'TEXTAREA' && document.activeElement.tagName !== 'SELECT') {
      e.preventDefault(); el.search.focus();
    }
    if (e.key === 'Escape') closeDrawers();
  });

  $('toggle-tree').addEventListener('click', function () { if (document.body.classList.contains('tree-open')) closeDrawers(); else { closeDrawers(); openDrawer('tree'); renderTree(); } });
  $('toggle-info').addEventListener('click', function () { if (document.body.classList.contains('info-open')) closeDrawers(); else { closeDrawers(); openDrawer('info'); } });
  el.scrim.addEventListener('click', closeDrawers);
  el.info.addEventListener('click', function (e) { if (e.target.closest('[data-close-info]')) closeDrawers(); });

  window.addEventListener('hashchange', route);
  route();
})();
